package dev.alextorres.vegas.desktop.ui.theme

import androidx.compose.material3.ColorScheme
import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.graphics.Color
import com.materialkolor.PaletteStyle
import com.materialkolor.dynamiccolor.ColorSpec
import com.materialkolor.rememberDynamicColorScheme

val DefaultThemeColor = Color(0xFFED5564)

@Composable
fun VegasTheme(
    seed: Color = DefaultThemeColor,
    pureBlack: Boolean = false,
    content: @Composable () -> Unit,
) {
    val base = rememberDynamicColorScheme(
        seedColor = seed,
        isDark = true,
        specVersion = ColorSpec.SpecVersion.SPEC_2025,
        style = PaletteStyle.TonalSpot,
    )
    val scheme = remember(base, pureBlack) { if (pureBlack) base.pureBlack() else base }
    MaterialTheme(colorScheme = scheme, content = content)
}

private fun ColorScheme.pureBlack() = copy(surface = Color.Black, background = Color.Black)
